    'Vacay: ваш особистий планувальник відпусток. Він показує, скільки днів відпустки у вас на рік, які з них уже відмічено і скільки лишилося. Сітка охоплює весь рік. На бічній панелі є вибір року, люди, з якими ви плануєте, календарі, якими з вами поділилися, легенда та ваше право на відпустку.',
