  'help.guide.tour-walk-day-times.step.2':
    'Задайте їй час початку в цей день: на вкладці «План» клацніть прогулянку в дні правою кнопкою миші, виберіть «Редагувати» й введіть «Початок».',
  'help.guide.tour-walk-google-import.title': 'Перетворіть піший маршрут Google Maps на міську прогулянку',
